TLM.f("Sancti/10-20",{"officium":"S. Joannis Cantii Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"Tractus":"Commune/C5","Evangelium":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 18:12-13"},{"k":"text","la":"Miserátio hóminis circa próximum: misericórdia autem Dei super omnem carnem. Qui misericórdiam habet, docet et érudit quasi pastor gregem suum."},{"k":"ref","la":"Ps 1:1"},{"k":"text","la":"Beátus vir, qui non ábiit in consílio impiórum, et in via peccatórum non stetit, et in cáthedra pestiléntiæ non sedit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Miserátio hóminis circa próximum: misericórdia autem Dei super omnem carnem. Qui misericórdiam habet, docet et érudit quasi pastor gregem suum."}],"Oratio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, sancti Joánnis Confessóris exémplo in sciéntia Sanctórum proficiéntes atque áliis misericórdiam exhibéntes; ejus méritis, indulgéntiam apud te consequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli"},{"k":"ref","la":"Jac 2:12-17"},{"k":"text","la":"Carissimi: Sic loquímini, et sic fácite sicut per legem libertátis incipiéntes judicári. Judícium enim sine misericórdia illi, qui non fecit misericórdiam: superexáltat autem misericórdia judícium. Quid próderit, fratres mei, si fidem quis dicat se habére, ópera autem non hábeat? Numquid poterit fides salváre eum? Si autem frater et soror nudi sint, et indígeant victu quotidiáno, dicat autem áliquis ex vobis illis: Ite in pace, calefacímini et saturámini: non dedéritis autem eis, quæ necessária sunt córpori, quid próderit? Sic et fides, si non hábeat ópera, mórtua est in semetípsa."}],"Graduale":[{"k":"ref","la":"Ps 106:8-9"},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus: et mirabília ejus fíliis hóminum."},{"k":"text","la":"Quia satiávit ánimam inánem: et ánimam esuriéntem satiavit bonis. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 31:20"},{"k":"text","la":"Manum suam apéruit ínopi: et palmas suas exténdit ad páuperem. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 31:20"},{"k":"text","la":"Manum suam apéruit ínopi: et palmas suas exténdit ad páuperem."},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:35-40"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet."}],"Offertorium":[{"k":"ref","la":"Job 29:14-16"},{"k":"text","la":"Justítia indútus sum, et vestívi me, sicut vestiménto et diadémate, judício meo. Oculus fui cæco et pes claudo: pater eram páuperum."}],"Secreta":[{"k":"text","la":"Has, quǽsumus, Dómine, hóstias sancti Joánnis Confessóris tui méritis benígnus assúme: et præsta; ut, te super ómnia et omnes propter te diligéntes, corde tibi et ópere placeámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 6:38"},{"k":"text","la":"Date, et dábitur vobis: mensúram bonam et confértam et coagitátam et supereffluéntem dabunt in sinum vestrum."}],"Postcommunio":[{"k":"text","la":"Pretiósi Córporis et Sánguinis tui, Dómine, pasti delíciis, tuam súpplices deprecámur clementiam: ut, sancti Joánnis Confessóris tui méritis et exémplis, ejúsdem caritátis imitatóres effécti, consórtes simus et glóriæ:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"f74d3c6b8e063f8a":{"t":"Sir 18, 12-13, Ps 1, 1\n(Sir 18, 12-13) Čovjek se smiluje svome bližnjemu, a Bog se smiluje svim ljudima. On pokazuje milosrđe, upućuje i vodi kao pastir svoje stado. (Ps 1, 1) Blago čovjeku koji ne slijedi savjet bezbožnika, niti se zaustavlja na putu grješnika, niti sjedi u društvu zločinaca.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 18, 12-13) Čovjek se smiluje svome bližnjemu, a Bog se smiluje svim ljudima. On pokazuje milosrđe, upućuje i vodi kao pastir svoje stado.","kn":"(Crkv. 18, 12, 13). Čovjek se smiluje onome, koji mu je bliz, a Bog se smiluje svima Ludima. Božje je milosrđe i on poučaje i vodi kao pastu svoje stado. (Ps. 1, 1.) Blago čovjeku, koji ne slijedi misli bezbožnika i koji nije pošao putem griješnika, niti je sjedio u krugu porugljivaca. Slava Ocu . . . Čovjek ...","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"acecb10252975333":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da po primjeru svetoga Ivana priznavaoca napredujemo u znanju svetih i drugima iskazujemo milosrđe te tako po njegovim zaslugama postignemo tvoje oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da po primjeru blaženoga Ivana, priznavaoca, napredujući u znanju svetih i drugima iskazujući milosrđe, njegovim zaslugama, postignemo Tvoje oproštenje, po G. n.","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"464741d819adb3b0":{"t":"Jak 2, 12-17\nČitanje Poslanice bl. Jakova apostola. Predragi, tako govorite i tako činite kao oni koji imaju biti suđeni po zakonu slobode. Onome koji ne postupa milosrdno sudit će se bez milosrđa. Milosrđe je uzvišenije od pravde. Kakva je korist, braćo moja, ako tko kaže da ima vjeru a nema djela? Zar ga može spasiti vjera? Ako su brat ili sestra goli, ili bez svakidašnje hrane, pa im netko od vas reče: Idite u miru, ogrijte se i nasitite, a ne date i ono što je potrebno za tijelo, kakva korist? Tako je i vjera bez djela sama za se mrtva.","kn":"Čitanje poslanice bi. Jakoba apostola (2, 12-17). Predragi! Tako govorite i tako činite kao oni, koji imadiu biti zakoiniom, slobode siuđeni. Jer će onome biti sud bez milosrđa, koji ne čini milosrđe, jer se ponosi milosrđe protiv suda. Kakva je korist, braćo moja, ako tko kaže, da ima vjeru, a djela nema? Zar ga može vjera spasiti? Ako brat ili sestra goli budu ili su bez svakidašnje' hrane,’ a reče im koji od vas: idite s mirom, grijte se i nasitite se, a ne date im, što im je potrebito za tijelo, kakva korist? Tako i' vjera, ako nema djela, mrtva je u samoj sebi.","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"4e693602ba5da410":{"t":"Ps 106, 8-9\nNeka zahvaljuju Gospodinu radi milosrđa njegova i radi čudesa njegovih koja je učinio sinovima ljudskim, jer je gladne nahranio i ispunio dobrima žedne duše.\n\nIzr 31, 20\n<i>Aleluja</i>, <i>aleluja</i>.\nRuku svoju otvara siromahu i dlane svoje pruža ubogomu. <i>Aleluja</i>.","kn":"(Ps. 106, 8, 9). Neka hvale Gospodina radi milosrđa njegova i radi čudesa, iskazanih sinovima ljudskim; jer je nahranio gladne i izgladnjele je 'napunio dobara.' Aleluja, a'leluja.\n\n(Posl. 31, 20.) Otvorio je ruku svoju bijednomu i siromahu, aleluja.","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"52bdf7255321563a":{"t":"Lk 12, 35-40\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Isus reče svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama, a vi budite slični slugama koji očekuju svojega gospodara, kada se vraća sa svadbe, da mu smjesta otvore vrata, čim dođe i pokuca. Blago onim slugama koje gospodar kada dođe nađe budne! Uvjeravam vas, da će se sam pripasati, narediti im da sjednu za stol i poslužiti ih. Blago tim slugama, ako ih nađe tako došao on bilo o drugoj, ili o trećoj straži. Pazite: Kada bi domaćin znao u koji čas dolazi tat, ne bi dopustio potkopati svoje kuće. Zato budite pripravni i vi, jer će Čovječji Sin doći u čas, kada vi i ne slutite.","kn":"t Slijedi sveto evanđelje po Luki (12, 35-40). U ono vrijeme reče Isus svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama. A vi sami budite kao oni ljudi, koji očekuju svoga gospodara, kad se vraća sa svadbe, da čim dođe i pokuca, smjesta mu otvore vrata. Blago onim slugama, koje gospodar došav nađe budne. Zaista vam kažem, da će se sam priipasati i posaditi Ih za stol i sam će ih poslužiti. Blago tim slugama, ako ih zateče tako, ako dođe o drugoj ili trećoj straži. Znajte ovo: Kad bi domaćin znao, u koji čas dolazi tat, zaista bi bdio i ne bi dao potkopati svoje kuće. I vi budite spremni, jer u čas, kad vi ne mislite, doći će Sin čovječji.","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"},"186866dcca01aa6f":{"t":"Job 29, 14-16\nObukao sam se u pravednost, a čestit život je moja odjeća i moja kruna. Slijepcu sam bio oko, hromom noga. Bio sam otac siromaha.","kn":"(Job. 29, 14-16). Odjeven sam pravdom i odjenuh se kao odjećom i krunom čestitim životom. Slijepcu sam bio oko, hromomu noga, bio sam otac siromaha., .","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"7614b3c81bce247c":{"t":"Dobrostivo primi, molimo, Gospodine, ove darove po zaslugama svetog Ivana priznavaoca svoga i podaj da, ljubeći tebe nada sve i sve zbog tebe, ugodimo tebi srcem i djelima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi., molimo. Gospodine, ove ^tve zaslugama svetog priznavaoca svoga Ivana i podaj, da ljubeći Tebe nada sve, a sve drugo Tebe radi, ugodimo Tebi srcem i djelima, po G. n.","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"98ff1f8ced48e687":{"t":"Lk 6, 38\nDajte i dat će vam se. Dat će vam mjeru dobru, punu, stresenu i preobilatu.","kn":"(Lk. 6, 38). Dajte i dat će vam se, mjeru dobru, nabijenu, stresenu, preobilatu, dat će u naručje vaše.","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"},"78d27594d12593e6":{"t":"<i>Pomolimo se</i>.\nNahranjeni blagovanjem dragocjenoga tijela i krvi tvoje, Gospodine, ponizno molimo tvoju blagost da po zaslugama i primjeru svetoga Ivana priznavaoca tvoga nasljedujemo njegovu ljubav te budemo dionici njegove slave:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Nahranjeni, Gospodine, preslatkim i dragocjenim tijelom i krvlju Tvojom ponizno molimo Tvoju blagodat, da zagovorom i zaslugama svetog priznavaoca Tvoga Ivana nasljedujemo nje govu ljubav i tako postanemo dionicima njegove slave; koji živiš i kraljuješ . . .","knRef":"Kniewald 1942, str. 744–745 (snimka 373) (OCR)"}}});
